package com.isoform

import com.facebook.react.bridge.ReadableArray
import com.facebook.react.module.annotations.ReactModule
import com.facebook.react.uimanager.SimpleViewManager
import com.facebook.react.uimanager.ThemedReactContext
import com.facebook.react.uimanager.ViewManagerDelegate
import com.facebook.react.viewmanagers.IsoImageViewManagerDelegate
import com.facebook.react.viewmanagers.IsoImageViewManagerInterface

/**
 * Bridge between Fabric and `IsoImageView`: props, `ref` commands and events.
 * `IsoImageViewManagerInterface`/`Delegate` are generated by Codegen from
 * `src/adapters/react-native/image/native/IsoImageViewNativeComponent.ts`.
 *
 * The source props arrive one by one (`uri`, `cacheKey`, `headers`), so they are kept
 * here per view and handed over together; the load starts in `onAfterUpdateTransaction`,
 * once every prop of the update is set.
 */
@ReactModule(name = IsoImageViewManager.NAME)
class IsoImageViewManager :
  SimpleViewManager<IsoImageView>(),
  IsoImageViewManagerInterface<IsoImageView> {

  private val delegate = IsoImageViewManagerDelegate(this)

  /** The pending source of each view (uri, cache key, headers). */
  private class Source(var uri: String = "", var cacheKey: String = "", var headers: ReadableArray? = null)
  private class Placeholder(var uri: String = "", var blurhash: String = "")

  private val sources = java.util.WeakHashMap<IsoImageView, Source>()
  private val placeholders = java.util.WeakHashMap<IsoImageView, Placeholder>()

  override fun getDelegate(): ViewManagerDelegate<IsoImageView> = delegate

  override fun getName(): String = NAME

  override fun createViewInstance(context: ThemedReactContext): IsoImageView = IsoImageView(context)

  override fun onAfterUpdateTransaction(view: IsoImageView) {
    super.onAfterUpdateTransaction(view)
    sources[view]?.let { view.setSource(it.uri, it.cacheKey, it.headers) }
    placeholders[view]?.let { view.setPlaceholder(it.uri, it.blurhash) }
    view.commit()
  }

  override fun onDropViewInstance(view: IsoImageView) {
    view.release()
    sources.remove(view)
    placeholders.remove(view)
    super.onDropViewInstance(view)
  }

  private fun source(view: IsoImageView) = sources.getOrPut(view) { Source() }
  private fun placeholder(view: IsoImageView) = placeholders.getOrPut(view) { Placeholder() }

  // ── props ──

  override fun setUri(view: IsoImageView, value: String?) { source(view).uri = value.orEmpty() }

  override fun setCacheKey(view: IsoImageView, value: String?) { source(view).cacheKey = value.orEmpty() }

  override fun setHeaders(view: IsoImageView, value: ReadableArray?) { source(view).headers = value }

  override fun setPlaceholderUri(view: IsoImageView, value: String?) { placeholder(view).uri = value.orEmpty() }

  override fun setBlurhash(view: IsoImageView, value: String?) { placeholder(view).blurhash = value.orEmpty() }

  override fun setContentFit(view: IsoImageView, value: String?) = view.setFit(value ?: "cover")

  override fun setPositionX(view: IsoImageView, value: Double) = view.setPositionX(value)

  override fun setPositionY(view: IsoImageView, value: Double) = view.setPositionY(value)

  override fun setTransition(view: IsoImageView, value: Double) = view.setTransition(value)

  override fun setTintColor(view: IsoImageView, value: Int?) = view.setTint(value)

  override fun setBlurRadius(view: IsoImageView, value: Double) = view.setBlurRadius(value)

  override fun setCachePolicy(view: IsoImageView, value: String?) = view.setCachePolicy(value ?: "memoryDisk")

  override fun setPriority(view: IsoImageView, value: String?) = view.setPriority(value ?: "normal")

  override fun setAutoplay(view: IsoImageView, value: Boolean) = view.setAutoplay(value)

  override fun setZoomable(view: IsoImageView, value: Boolean) = view.setZoomable(value)

  override fun setMaxZoom(view: IsoImageView, value: Double) = view.setMaxZoom(value)

  override fun setDoubleTapZoom(view: IsoImageView, value: Double) = view.setDoubleTapZoom(value)

  override fun setRotatable(view: IsoImageView, value: Boolean) = view.setRotatable(value)

  override fun setCornerRadius(view: IsoImageView, value: Double) = view.setCornerRadius(value)

  // ── commands ──

  override fun zoomTo(view: IsoImageView, scale: Double, focusX: Double, focusY: Double, animated: Boolean) = view.zoomTo(scale, focusX, focusY, animated)

  override fun resetZoom(view: IsoImageView, animated: Boolean) = view.resetZoom(animated)

  override fun rotateTo(view: IsoImageView, degrees: Double, animated: Boolean) = view.rotateTo(degrees, animated)

  override fun play(view: IsoImageView) = view.play()

  override fun pause(view: IsoImageView) = view.pause()

  override fun reload(view: IsoImageView) = view.reload()

  // ── events (native name → JS prop) ──

  override fun getExportedCustomDirectEventTypeConstants(): Map<String, Any> =
    IsoImageView.EVENTS.associateWith { mapOf("registrationName" to "on" + it.removePrefix("top")) }

  companion object {
    const val NAME = "IsoImageView"
  }
}
